function a3Model(m,i){return `<section class="project-section a3-model-row${i%2?' is-reversed':''}" data-a3-model="${m.id}" aria-labelledby="a3-${m.id}-title"><figure class="a3-model-photo">${image(m.photo,m.alt,'A³ '+m.title)}<figcaption>Visualització de projecte · A³ ${m.title}</figcaption></figure><div class="a3-model-copy"><p class="a3-model-kind">${m.kind}</p><h2 id="a3-${m.id}-title">A<sup>3</sup> ${m.title}</h2><p>${m.copy}</p><div class="a3-action"><div><h3>Accionament</h3><p>${m.action}</p></div>${image('a3-editorial/action-'+m.id+'.webp','Esquema original d’obertura, tancament i temperatura d’A³ '+m.title,'Accionament · A³ '+m.title)}</div></div></section>`}
function a3(){const p=projects[0];return `<article class="project a3-editorial">${opening(p,0,'A³ Collection · Visió de família')}
 <section class="project-summary">${facts([['Projecte','A³ Collection'],['Any','2025 · Curs 2025–26'],['Context','Projecte acadèmic · ESDAPC'],['Autoria','Marc Moncunill<br>Blanca Gordillo'],['Àmbit','Disseny de producte · Griferia'],['Treball','Idea, proves de forma i models 3D']])}<div><h2>Una col·lecció.<br>Cinc models.</h2><p>A³ Collection reuneix cinc models d’aixetes per a lavabo, cuina i paret, units per un perfil triangular. Cada variant adapta l’alçada, la instal·lació i la posició de la maneta al seu ús.</p><p>El nom combina aixeta, aigua i arquitectura. La geometria de tres arestes i els acabats compartits donen coherència al conjunt.</p><a class="a3-document-link" href="assets/a3-editorial/plans.pdf" target="_blank" rel="noopener">Plànols de la col·lecció ↗</a></div></section>
 <section class="project-section a3-publication" aria-labelledby="a3-publication-title"><div class="a3-section-intro"><h2 id="a3-publication-title">Publicació<br>no estandarditzada</h2><p>La col·lecció es presenta en una publicació amb enquadernació manual i cosit visible. Les pàgines translúcides superposen dibuixos i renders, relacionant les diferents variants.</p></div><div class="a3-book-grid"><figure class="a3-book-cover">${image('a3-editorial/publication-1.webp','Publicació física A³ Collection amb cosit visible, fotografiada sobre fons vermell','Publicació no estandarditzada · Coberta')}<figcaption>La publicació física, amb el cosit a la vista.</figcaption><a class="a3-document-link" href="assets/a3-editorial/catalogue.pdf" target="_blank" rel="noopener">Obrir el catàleg (PDF) ↗</a></figure><div class="a3-book-spreads"><figure>${image('a3-editorial/publication-2.webp','Pàgines obertes de la publicació A³ amb un full translúcid superposat','Publicació · Transparències')}<figcaption>Les pàgines semitransparents combinen dibuixos i imatges.</figcaption></figure><figure class="a3-book-detail">${image('a3-editorial/publication-3.webp','Detall original de la publicació oberta amb les variants de la col·lecció','Publicació · Família de models')}</figure></div></div></section>
 <div class="a3-models-heading"><h2>Lavabo, cuina i paret</h2><p>Cinc models per a espais i usos diferents.</p></div>
 ${a3Models.map(a3Model).join('')}
 <section class="project-section a3-context" aria-labelledby="a3-context-title"><div class="a3-section-intro"><h2 id="a3-context-title">La família,<br>en context</h2><p>El model de cuina en negre i terracota, amb un detall del perfil triangular que identifica la col·lecció.</p></div><figure class="a3-context-wide">${image('a3-kitchen-detail.webp','Model de cuina negre amb la punta recollida, sobre una pica negra','A³ Kitchen · Punta recollida')}</figure><div class="a3-context-images"><figure class="a3-context-shape">${image('a3-family.webp','Detall de la forma triangular i corbada de l’aixeta','A³ · Detall de la forma')}</figure><figure class="a3-context-terracotta">${image('a3-editorial/render-kitchen-terracotta.webp','Model de cuina terracota en una cuina de tons clars','A³ Kitchen · Terracota')}</figure></div></section>
 <section class="project-section a3-development" aria-labelledby="a3-development-title"><div class="a3-section-intro"><h2 id="a3-development-title">De la línia<br>al volum</h2><p>Els esbossos inicials exploren el perfil triangular i la curvatura del broc. El modelatge 3D permet ajustar les proporcions, els encaixos i la relació entre el cos i la maneta.</p></div><div class="a3-render-pair">${figure('a3-sketch-1.webp','Primer esbós original del desenvolupament d’A³','Primers esbossos','')}${figure('a3-sketch-2.webp','Segon esbós original del procés formal d’A³','Variacions de forma','')}</div></section>
 <p class="project-note">Projecte acadèmic desenvolupat per Marc Moncunill i Blanca Gordillo. Dibuixos, models 3D i renders del projecte.</p>${next(projects[1])}</article>`}
